import React, { useState, useCallback, useEffect } from 'react';
import useSchemaStore from '../store/schemaStore';

const Outputcontainer = ({ shouldDisplaySchemaOutput, shouldDisplaySqlOutput }) => {
  const { xmlOutput, mysqlOutput, jsonOutput, downloadXML, copyXML, downloadSQL, copySQL, downloadJSON, copyJSON } = useSchemaStore();
  const [copied, setCopied] = useState('');
  const [prism, setPrism] = useState(null);
  const [showWhitelistInfo, setShowWhitelistInfo] = useState(false);
  const [copiedCommand, setCopiedCommand] = useState(false);

  const command = 'php bin/magento setup:db-declaration:generate-whitelist --module-name=VendorName_ModuleName';

  const handleCopyCommand = async () => {
    try {
      await navigator.clipboard.writeText(command);
      setCopiedCommand(true);
      setTimeout(() => setCopiedCommand(false), 1800);
    } catch (err) {
      console.error('Failed to copy command', err);
    }
  };

  // Dynamically load Prism and required languages/styles only when outputs are present
  useEffect(() => {
    let mounted = true;
    const shouldLoad = (xmlOutput && xmlOutput.length) || (mysqlOutput && mysqlOutput.length) || (jsonOutput && jsonOutput.length);
    if (!shouldLoad) return;

    // load prism and some common language components + a theme
    Promise.all([
      import('prismjs'),
      import('prismjs/components/prism-markup'), // xml/html
      import('prismjs/components/prism-json'),
      import('prismjs/components/prism-sql'),
      import('prismjs/themes/prism.css'),
    ])
      .then(([PrismModule]) => {
        if (!mounted) return;
        // Wait until the theme CSS is applied to avoid an initial flash of unstyled white code.
        const checkCssApplied = (tries = 0) => {
          try {
            for (const sheet of Array.from(document.styleSheets)) {
              // Some styleSheets may be cross-origin; accessing cssRules may throw — ignore those
              const rules = sheet.cssRules || sheet.rules;
              if (!rules) continue;
              for (const r of Array.from(rules)) {
                if (r.selectorText && (r.selectorText.includes('.token') || r.selectorText.includes('.language-'))) {
                  if (mounted) setPrism(PrismModule);
                  return;
                }
              }
            }
          } catch (e) {
            // ignore security errors
          }

          if (tries < 8) {
            // retry shortly (up to ~800ms)
            setTimeout(() => checkCssApplied(tries + 1), 100);
          } else if (mounted) {
            // give up and still set Prism to avoid blocking forever
            setPrism(PrismModule);
          }
        };

        checkCssApplied();
      })
      .catch(() => {
        if (mounted) setPrism(null);
      });

    return () => { mounted = false; };
  }, [xmlOutput, mysqlOutput, jsonOutput]);

  const showCopied = useCallback((type) => {
    setCopied(type);
    setTimeout(() => setCopied(''), 1800);
  }, []);

  const handleCopyXML = async () => {
    try {
      const ok = await copyXML();
      if (ok) showCopied('xml');
    } catch (e) { }
  };

  const handleCopyJSON = async () => {
    try {
      const ok = await copyJSON();
      if (ok) showCopied('json');
    } catch (e) { }
  };

  const handleCopySQL = async () => {
    try {
      const ok = await copySQL();
      if (ok) showCopied('sql');
    } catch (e) { }
  };

  return (
      <div className="output-container">
        {shouldDisplaySchemaOutput && (
          <div className="output-section">
            <h3>
              <b>db_schema.xml</b>
            </h3>
            {prism && prism.languages && prism.languages.markup ? (
              <pre className="language-markup"><code dangerouslySetInnerHTML={{ __html: prism.highlight(xmlOutput || '', prism.languages.markup, 'markup') }} /></pre>
            ) : (
              <pre style={{whiteSpace: 'pre-wrap'}}>{xmlOutput}</pre>
            )}
            <button
              className="btn btn-secondary mr-2"
              onClick={downloadXML}
            >
              Download
            </button>
            <button className="btn btn-secondary" onClick={handleCopyXML}>
              Copy Schema
            </button>
            {copied === 'xml' && <span className="text-success" style={{ marginLeft: 8, fontWeight: 600 }}>Copied!</span>}
          </div>
        )}
        <div className="output-sub-container">
          {shouldDisplaySchemaOutput && (
            <div className="output-section">
              <h3>
                <b>db_schema_whitelist.json</b>
              </h3>
              {prism && prism.languages && prism.languages.json ? (
                <pre className="language-json"><code dangerouslySetInnerHTML={{ __html: prism.highlight(jsonOutput || '', prism.languages.json, 'json') }} /></pre>
              ) : (
                <pre style={{whiteSpace: 'pre-wrap'}}>{jsonOutput}</pre>
              )}
              <button
                className="btn btn-secondary mr-2"
                onClick={downloadJSON}
              >
                Download
              </button>
              <button className="btn btn-secondary mr-2" onClick={handleCopyJSON}>
                Copy JSON
              </button>
              <button className="btn btn-secondary" onClick={() => setShowWhitelistInfo(!showWhitelistInfo)}>
                  Whitelist Command
              </button>
              {showWhitelistInfo && (
                <div style={{ padding: '12px', backgroundColor: '#f9f9f9', borderRadius: '4px', marginTop: '8px', border: '1px solid #ddd' }}>
                  <p style={{ margin: '0 0 8px 0' }}>This command generates the <code>db_schema_whitelist.json</code> file required by Magento:</p>
                  <code style={{ display: 'block', padding: '8px', backgroundColor: '#f5f5f5', borderRadius: '4px', marginBottom: '8px', wordBreak: 'break-all' }}>
                    {command}
                  </code>
                  <b>Usage:</b>
                  <ul style={{ margin: '8px 0', paddingLeft: '20px' }}>
                    <li>
                      Replace <code>VendorName_ModuleName</code> with your actual module name
                    </li>
                    <li>
                      Use <code>--module-name=all</code> to generate whitelist for all modules
                    </li>
                  </ul>
                  <button 
                    className="btn btn-sm btn-primary" 
                    onClick={handleCopyCommand}
                  >
                    {copiedCommand ? '✓ Copied!' : 'Copy Command'}
                  </button>
                </div>
              )}
              {copied === 'json' && <span className="text-success" style={{ marginLeft: 8, fontWeight: 600 }}>Copied!</span>}
            </div>
          )}

          {shouldDisplaySqlOutput && (
            <div className="output-section">
              <h3>
                <b>MySQL Query</b>
              </h3>
              {prism && prism.languages && prism.languages.sql ? (
                <pre className="language-sql"><code dangerouslySetInnerHTML={{ __html: prism.highlight(mysqlOutput || '', prism.languages.sql, 'sql') }} /></pre>
              ) : (
                <pre style={{whiteSpace: 'pre-wrap'}}>{mysqlOutput}</pre>
              )}
              <button
                className="btn btn-secondary mr-2"
                onClick={downloadSQL}
              >Download</button>
              <button className="btn btn-secondary" onClick={handleCopySQL}>
                Copy Query
              </button>
              {copied === 'sql' && <span className="text-success" style={{ marginLeft: 8, fontWeight: 600 }}>Copied!</span>}
            </div>
          )}
        </div>
      </div>
  );
};

export default Outputcontainer;